import { Suspense } from 'react';
import Canvas from '../SafeCanvas';
import { OrbitControls, PerspectiveCamera } from '@react-three/drei';
import { motion } from 'framer-motion';
import Chapter from '../Chapter';
import F1Car from '../F1Car';
import siteCopy from '../../data/siteCopy.json';

const Chapter4Robotics = () => {
  const { milestones } = siteCopy;
  const copy = milestones.chapters.find((chapter) => chapter.id === 'robotics');

  if (!copy) {
    return null;
  }

  return (
    <Chapter id="robotics" className="bg-gradient-to-b from-bg-light-secondary dark:from-bg-dark-secondary to-bg-light dark:to-bg-dark">
      <div className="min-h-screen py-24 flex flex-col lg:flex-row-reverse items-center justify-center gap-8 px-8 lg:px-16">

        {/* 3D Scene - Right Side */}
        <div className="w-full lg:w-1/2 h-[50vh] lg:h-[70vh] ">
          <Canvas gl={{ antialias: true, alpha: true }} dpr={[1, 1.5]}>
            <PerspectiveCamera makeDefault position={[4, 2, 4]} />

            <ambientLight intensity={10} />
            <directionalLight position={[5, 5, 5]} intensity={20} color="#FFFFFF" />
            <pointLight position={[-3, 2, -2]} intensity={1.8} color="#FFD700" />
            <pointLight position={[3, 2, 2]} intensity={1.5} color="#FFFFFF" />

            <Suspense fallback={null}>
              <F1Car />
            </Suspense>

            <OrbitControls
              enableZoom={false}
              enablePan={false}
              
              autoRotate
              autoRotateSpeed={0.3}
              maxPolarAngle={Math.PI / 1.8}
              minPolarAngle={Math.PI / 3}
              
            />
          </Canvas>
        </div>

        {/* Content - Left Side */}
        <div className="w-full lg:w-1/2 flex flex-col justify-center text-left space-y-6">
          <motion.div
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: false }}
            transition={{ duration: 0.8, delay: 0.2 }}
          >
            <h2 className="font-serif text-4xl md:text-5xl lg:text-6xl text-text-light dark:text-white-warm mb-4">
              {copy.number}
            </h2>
            <h3 className="font-display text-3xl md:text-4xl text-bronze dark:text-champagne mb-6">
              {copy.title}
            </h3>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: false }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="space-y-4"
          >
            {copy.paragraphs.map((paragraph, index) => (
              <p
                key={index}
                className={`font-sans ${index === 0 ? 'text-lg md:text-xl text-text-light/90 dark:text-cream/90' : 'text-base md:text-lg text-text-light/80 dark:text-cream/80'} leading-relaxed`}
              >
                {paragraph}
              </p>
            ))}
          </motion.div>

          {copy.ctaUrl && copy.ctaLabel && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: false }}
              transition={{ duration: 0.6, delay: 0.6 }}
              className="pt-4"
            >
              <a
                href={copy.ctaUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block px-8 py-3 border border-amber/30 hover:border-amber/60 hover:bg-amber/5 rounded-sm transition-all duration-300"
              >
                <p className="font-mono text-sm text-amber tracking-wider">
                  {copy.ctaLabel}
                </p>
              </a>
            </motion.div>
          )}
        </div>
      </div>

    </Chapter>
  );
};

export default Chapter4Robotics;
